      -- incubators added stay.
      local cap0 = fid and lp("farm_cap", fid.id)
      local pens0 = (lp("farm_state").farms or {})[1].pens
      local pens1 = fid and lp("farm_add_pens", fid.id, 3 * math.max(8, pens0) - pens0)
      S.pens_added = true
