    -- Its incubators within its most, by its evolution (farm.lua pens_max): 16 to evolution 0.5, 28 at 1.
    -- (Not where the test added incubators itself: farm_add_pens, past any most.)
    for _, g in pairs(S.pens_added and {} or lp("farm_state").farms or {}) do
      check("farm: its incubators within its most", g.pens <= g.pens_max, string.format("%d of %d", g.pens, g.pens_max))
      if mix ~= "bigpens" and (g.evo or 0) <= 0.5 then check("farm: its most 16 at evolution 0.5 or less", g.pens_max == 16, tostring(g.pens_max)) end
    end
    if mix == "bigpens" then
      check("farm: bigpens, at evolution 1 its most is 28, and it grew past 16", S.pens_max == 28 and (S.pens_most or 0) > 16,
        serpent.line({most = S.pens_most, max = S.pens_max}))
      return
    end
    if mix == "siegepoor" then
      check("farm: siegepoor, laid, its stock rich", #(S.sieges or {}) > 0 and S.stocked == 10, serpent.line({sieges = #(S.sieges or {}), stocked = S.stocked}))
      return
    end
    if mix == "evocap" then
      check("farm: evocap, set 0.3 past the wild's, it came down to its lead", S.evo_set and e.evo
        and math.abs(e.evo - math.min(1, e.wild + 0.15)) < 0.002, serpent.line({set = S.evo_set, e = e}))
      return
    end
    if mix == "techs" then
      info(string.format("farm techs: after 7 min %s; after 14 min %s", serpent.line(S.hungry), serpent.line(S.fed_again)))
      -- (An incubator its creep took after the killing has a cell of its own, fed five minutes from its building.)
      check("farm: its technicians dead, the biochambers stopped and the incubators unfed", S.hungry
        and S.hungry.unfed >= S.pens0 and S.hungry.working <= S.hungry.pens - S.pens0, serpent.line(S.hungry))
      check("farm: technicians came back by pod and the feed with them, no incubator lost", S.fed_again
        and S.fed_again.techs >= 2 and S.fed_again.working == S.fed_again.pens and S.fed_again.unfed == 0
        and S.fed_again.pens >= S.pens0, serpent.line(S.fed_again))
      return
    end
    if mix == "killed" then
      check("farm: every pen dead, the farm gone", S.after and #S.after.farms == 0, serpent.line(S.after))
